import ast, contextlib, hashlib, io, json, sys
from datetime import datetime
from pathlib import Path as RealPath, PurePosixPath
from types import SimpleNamespace as NS
project=RealPath('C:/Users/gb/projects/demo_dual_axis_20261002')
trace=project/'.aris/traces/experiment-bridge/2026-10-03_anytoany49'
helper=RealPath('C:/Users/gb/.codex_tmp/demo_anytoany_deploy_20261003.py')
helper_source=helper.read_text(encoding='utf-8');helper_tree=ast.parse(helper_source)
prior_harness=ast.parse(json.loads((trace/'002-mock-harness.json').read_text(encoding='utf-8'))['source'])
classes=[n for n in prior_harness.body if isinstance(n,ast.ClassDef) and n.name in ('MemoryFS','MemoryPath','NSContext') or isinstance(n,ast.FunctionDef) and n.name=='dump']
exec(compile(ast.Module(body=classes,type_ignores=[]),'<mock-paths>','exec'),globals())
def assigned(name):return ast.literal_eval(next(n.value for n in helper_tree.body if isinstance(n,ast.Assign) and any(isinstance(t,ast.Name) and t.id==name for t in n.targets)))
files=assigned('files');dependencies=assigned('dependencies')
source_hashes={name:hashlib.sha256((project/name).read_bytes()).hexdigest() for name in files}
helper_hash=hashlib.sha256(helper.read_bytes()).hexdigest()
helper_nodes=[n for n in helper_tree.body if not isinstance(n,(ast.Import,ast.ImportFrom)) and not(isinstance(n,ast.Expr) and isinstance(n.value,ast.Call) and ast.unparse(n.value.func)=='sys.path.insert')]
helper_ast=compile(ast.Module(body=helper_nodes,type_ignores=[]),str(helper),'exec')

hosts={'2026':('/data/gaob/Re-ID/DeMo-DualAxis','/data/gaob/Re-ID/conda-envs/tri_reid/bin/python'),
       '2027':('/data/gb/Re-ID/DeMo-DualAxis','/data/gb/Re-ID/conda-envs/tri_reid/bin/python')}
train={'2026':'runs/axis_collaboration_v5_mass/development','2027':'runs/axis_collaboration_v4_missing_development27_input'}
variants={'2026':'axis_mass_fullref','2027':'demo'}

def deploy_case(fault=None):
    local=MemoryFS();remote={host:MemoryFS() for host in hosts};gpu={host:{0:20,1:24000,2:20,3:20} for host in hosts};disk={host:2_000_000_000 for host in hosts}
    remote_calls=[];copies=[];launches=[];gpu_queries=[];scripts=[];expected_demo={}
    all_names=set(dependencies)|set(files)|{'mass_axis_collaboration.py','run_mass_experiment.py'}
    for name in all_names:local.path(str(project/name)).write_bytes((project/name).read_bytes())
    local.path(str(helper)).write_bytes(helper.read_bytes())
    for host,(root,python) in hosts.items():
        for name in set(dependencies)|({'mass_axis_collaboration.py','run_mass_experiment.py'} if host=='2026' else set()):remote[host].path(root+'/'+name).write_bytes((project/name).read_bytes())
        for dataset in ('MSVR310','RGBNT201','RGBNT100'):
            name=dataset+'_'+variants[host]+'_s42';run=remote[host].path(root+'/'+train[host]+'/'+name)
            exit_file=run/'exit.json' if host=='2027' else run.parent/(name+'_exit.json')
            terminal={'status':'COMPLETE','epochs':50,'arguments':{'dataset':dataset,'variant':variants[host],'seed':42}}
            dump(run/'result.json',terminal);dump(exit_file,{'exit_code':0});(run/'best.pth').write_bytes(b'synthetic checkpoint '+name.encode());(run/'best_dev_arrays.npz').write_bytes(b'synthetic arrays '+name.encode())
            inputs=(run/'best.pth',run/'best_dev_arrays.npz',run/'result.json',exit_file)
            if host=='2027':expected_demo[name]={'files':{p.name:{'bytes':p.stat().st_size,'sha256':hashlib.sha256(p.read_bytes()).hexdigest()} for p in inputs}}
    review={'status':'PASS','blockers':[],'helper_sha256':helper_hash,'checked_source_sha256':dict(source_hashes)}
    if fault=='review_blocked':review['status']='BLOCKED';review['blockers']=['synthetic']
    if fault=='review_wrong_helper':review['helper_sha256']='wrong'
    if fault=='review_wrong_source':review['checked_source_sha256'][files[0]]='wrong'
    dump(local.path(str(project/'results/preflight/anytoany49_review.json')),review)
    dump(local.path(str(project/'results/preflight/axis_collaboration_v4_missing_development27_launch.json')),{'input_files':expected_demo})
    if fault in ('gpu0_busy26','gpu2_busy26','gpu3_busy26'):gpu['2026'][int(fault[3])]=500
    if fault=='disk26_small':disk['2026']=1_000_000_000
    if fault=='source26_changed':remote['2026'].path(hosts['2026'][0]+'/run_experiment.py').write_bytes(b'changed')
    if fault=='source26_already_staged':remote['2026'].path(hosts['2026'][0]+'/'+files[0]).write_bytes((project/files[0]).read_bytes())
    if fault=='output26_exists':remote['2026'].path(hosts['2026'][0]+'/runs/anytoany49_axis_mass_fullref_20261003').mkdir()
    if fault=='training26_exit1':dump(remote['2026'].path(hosts['2026'][0]+'/'+train['2026']+'/MSVR310_axis_mass_fullref_s42_exit.json'),{'exit_code':1})
    if fault=='gpu27_busy':gpu['2027'][2]=500
    if fault=='mirror27_changed':remote['2027'].path(hosts['2027'][0]+'/'+train['2027']+'/MSVR310_demo_s42/best.pth').write_bytes(b'changed mirrored checkpoint')
    def command(argv):
        assert argv[0]=='scp';name=PurePosixPath(argv[-2]).name;host,destination=argv[-1].split(':',1)
        assert name in files and destination==hosts[host][0]+'/'+name
        remote[host].path(destination).write_bytes(local.path(argv[-2]).read_bytes());copies.append((host,name))
        if fault=='copied_source26_changed' and copies==[('2026',files[0]),('2026',files[1])]:remote['2026'].path(hosts['2026'][0]+'/'+files[0]).write_bytes(b'changed')
        return ''
    def remote_python(host,source):
        remote_calls.append(host);is_start='start_new_session' in source;scripts.append((host,'start' if is_start else 'guard',source))
        parsed=ast.parse(source)
        stripped=[n for n in parsed.body if not isinstance(n,(ast.Import,ast.ImportFrom))]
        def check_output(argv,text):
            assert argv==['nvidia-smi','--query-gpu=index,memory.used','--format=csv,noheader,nounits'];gpu_queries.append(host)
            return ''.join(str(i)+', '+str(m)+'\n' for i,m in gpu[host].items())
        def spawn(argv,cwd,start_new_session,stdout,stderr,env):
            assert str(cwd)==hosts[host][0] and start_new_session is True
            assert argv[:3]==[hosts[host][1],'-u','launch_anytoany_frozen.py']
            assert argv[argv.index('--variant')+1]==variants[host]
            assert argv[argv.index('--training-root')+1]==hosts[host][0]+'/'+train[host]
            assert argv[argv.index('--data-root')+1]==('/data/gaob/Re-ID/dataset' if host=='2026' else '/data/gb/Re-ID/dataset')
            assert argv[argv.index('--pretrained')+1]==('/data/gaob/Re-ID/Trifusion/pertrained-model/ViT-B-16.pt' if host=='2026' else '/data/gb/Re-ID/pretrained/ViT-B-16.pt')
            assert env['OMP_NUM_THREADS']==env['MKL_NUM_THREADS']==env['OPENBLAS_NUM_THREADS']=='4'
            output=remote[host].path(argv[argv.index('--output')+1]);output.mkdir()
            launches.append(host);return NS(pid=1000+len(launches))
        env=dict(hashlib=hashlib,json=json,Path=remote[host].path,shutil=NS(disk_usage=lambda path:NS(free=disk[host])),
                 subprocess=NS(check_output=check_output,Popen=spawn,STDOUT=-2),os=NS(environ={}),time=NS(time=lambda:1234))
        stream=io.StringIO()
        with contextlib.redirect_stdout(stream):exec(compile(ast.Module(body=stripped,type_ignores=[]),'<generated-remote-AST>','exec'),env)
        return stream.getvalue()
    env=dict(__file__=str(helper),Path=local.path,PROJECT=local.path(str(project)),HOSTS=dict(hosts),OPTIONS=[],
             command=command,remote_python=remote_python,json=json,hashlib=hashlib,datetime=datetime)
    failed=False
    try:
        with contextlib.redirect_stdout(io.StringIO()):exec(helper_ast,env)
    except AssertionError:failed=True
    receipt26=local.path(str(project/'results/preflight/anytoany49_2026_launch.json'))
    receipt27=local.path(str(project/'results/preflight/anytoany49_2027_launch.json'))
    if fault is None:
        assert not failed and launches==['2026','2027'] and copies==[('2026',n) for n in files]+[('2027',n) for n in files]
        assert receipt26.exists() and receipt27.exists()
        for path in (receipt26,receipt27):
            receipt=json.loads(path.read_text());assert receipt['availability']['gpus']=={'0':20,'2':20,'3':20}
    else:
        assert failed,fault
        if fault in ('gpu27_busy','mirror27_changed'):
            assert launches==['2026'] and receipt26.exists() and not receipt27.exists()
            stored26=receipt26.read_bytes();launch_count=len(launches)
            rerun_failed=False
            try:
                with contextlib.redirect_stdout(io.StringIO()):exec(helper_ast,env)
            except AssertionError:rerun_failed=True
            assert rerun_failed and len(launches)==launch_count and receipt26.read_bytes()==stored26
        else:assert launches==[] and not receipt26.exists() and not receipt27.exists()
    assert set(launches)<={'2026','2027'} and all(name.endswith('.py') for _,name in copies)
    return dict(fault=fault,guard_rejected=failed,controller_launches=launches,source_copies=copies,receipt26=receipt26.exists(),receipt27=receipt27.exists(),source_ASTs_parsed=len(scripts),real_remote_calls=0)

cases=[deploy_case(None)]+[deploy_case(f) for f in ('review_blocked','review_wrong_helper','review_wrong_source','gpu0_busy26','gpu2_busy26','gpu3_busy26','disk26_small','source26_changed','source26_already_staged','output26_exists','training26_exit1','copied_source26_changed','gpu27_busy','mirror27_changed')]
assert not any(n=='torch' or n.startswith('torch.') or n=='numpy' for n in sys.modules)
(trace/'003-deploy-mock-checks.json').write_text(json.dumps({'status':'PASS','scope':'Actual helper and generated remote AST executed with in-memory files and mocked subprocess/SSH; no actual remote or NN execution','cases':cases},indent=2),encoding='utf-8')
print(json.dumps({'status':'PASS','deploy_cases':len(cases),'host27_failure_preserves26_receipt':True,'rerun_does_not_restart26':True,'gpu1_busy_ignored':True,'copied_only_two_source_files_per_host':True},indent=2))
